CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "ApprovalStatus" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(25) NOT NULL,
    CONSTRAINT "PK_ApprovalStatus" PRIMARY KEY ("Id")
);

CREATE TABLE "ApproverRole" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(25) NOT NULL,
    CONSTRAINT "PK_ApproverRole" PRIMARY KEY ("Id")
);

CREATE TABLE "Area" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(25) NOT NULL,
    CONSTRAINT "PK_Area" PRIMARY KEY ("Id")
);

CREATE TABLE "ProjectType" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(25) NOT NULL,
    CONSTRAINT "PK_ProjectType" PRIMARY KEY ("Id")
);

CREATE TABLE "User" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(25) NOT NULL,
    "Email" character varying(25) NOT NULL,
    "Role" integer NOT NULL,
    CONSTRAINT "PK_User" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_User_ApproverRole_Role" FOREIGN KEY ("Role") REFERENCES "ApproverRole" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ApprovalRule" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MinAmount" numeric(18,2) NOT NULL,
    "MaxAmount" numeric(18,2) NOT NULL,
    "StepOrder" integer NOT NULL,
    "Area" integer,
    "Type" integer,
    "ApproverRoleId" integer NOT NULL,
    CONSTRAINT "PK_ApprovalRule" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ApprovalRule_ApproverRole_ApproverRoleId" FOREIGN KEY ("ApproverRoleId") REFERENCES "ApproverRole" ("Id"),
    CONSTRAINT "FK_ApprovalRule_Area_Area" FOREIGN KEY ("Area") REFERENCES "Area" ("Id"),
    CONSTRAINT "FK_ApprovalRule_ProjectType_Type" FOREIGN KEY ("Type") REFERENCES "ProjectType" ("Id")
);

CREATE TABLE "ProjectProposal" (
    "Id" uuid NOT NULL,
    "Title" character varying(255) NOT NULL,
    "Description" text NOT NULL,
    "EstimatedAmount" numeric(18,2) NOT NULL,
    "EstimatedDuration" integer NOT NULL,
    "CreateAt" timestamp with time zone NOT NULL,
    "Area" integer NOT NULL,
    "Type" integer NOT NULL,
    "Status" integer NOT NULL,
    "CreateBy" integer NOT NULL,
    CONSTRAINT "PK_ProjectProposal" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProjectProposal_ApprovalStatus_Status" FOREIGN KEY ("Status") REFERENCES "ApprovalStatus" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectProposal_Area_Area" FOREIGN KEY ("Area") REFERENCES "Area" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectProposal_ProjectType_Type" FOREIGN KEY ("Type") REFERENCES "ProjectType" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectProposal_User_CreateBy" FOREIGN KEY ("CreateBy") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ProjectApprovalStep" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "StepOrder" integer NOT NULL,
    "DecisionDate" timestamp with time zone,
    "Observations" text,
    "ProjectProposalId" uuid NOT NULL,
    "ApproverUserId" integer,
    "ApproverRoleId" integer NOT NULL,
    "Status" integer NOT NULL,
    CONSTRAINT "PK_ProjectApprovalStep" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProjectApprovalStep_ApprovalStatus_Status" FOREIGN KEY ("Status") REFERENCES "ApprovalStatus" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectApprovalStep_ApproverRole_ApproverRoleId" FOREIGN KEY ("ApproverRoleId") REFERENCES "ApproverRole" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectApprovalStep_ProjectProposal_ProjectProposalId" FOREIGN KEY ("ProjectProposalId") REFERENCES "ProjectProposal" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProjectApprovalStep_User_ApproverUserId" FOREIGN KEY ("ApproverUserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

