ALTER TABLE "User" ALTER COLUMN "Email" TYPE character varying(100);

ALTER TABLE "User" ADD "PasswordHash" character varying(255) NOT NULL DEFAULT '';

CREATE TABLE "RefreshToken" (
    "Id" uuid NOT NULL,
    "UserId" integer NOT NULL,
    "Token" character varying(255) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedByIp" character varying(100),
    "RevokedAt" timestamp with time zone,
    "RevokedByIp" character varying(100),
    "ReplacedByToken" character varying(255),
    "ReasonRevoked" character varying(255),
    CONSTRAINT "PK_RefreshToken" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshToken_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE CASCADE
);

